void tty_port_tty_set(struct tty_port *port, struct tty_struct *tty) /* <=== tty_port_tty_set */ 
{
	unsigned long flags;

	spin_lock_irqsave(&port->lock, flags);
	tty_kref_put(port->tty);
	port->tty = tty_kref_get(tty);
	spin_unlock_irqrestore(&port->lock, flags);
}

